css:
table, th, td {
  /*border: 1px solid;*/
  /*font-size: 11px;*/
}
table {
  border-collapse: collapse;
}
.print-format td{ 
  padding: 2px 4px 2px 4px !important; 
  
}
.print-preview{
    background-color:black !important;
}
   
@media all {
    .print-format {
        /*216mm or 21.6cm or 8.5in (inches)*/
        max-width: 21.1cm;
        width: 21.6cm;
        /*279mm or 26.9cm or 11.0in (inches)*/
        min-height: 26.9cm;
        height: 26.9cm;
        /* Margin from edge of page (padding) 0.0cm*/
        padding: 0.0cm 0.5cm 0.5cm 0.5cm;
        margin: 0.0cm 0.0cm  0.0cm  0.0cm ;
        float: left;
        /*background-color: rgba(255,2555,255,1.0);*/
        /*box-shadow: 0px 0px 9px rgba(0,0,0,0.5);*/
    }
    .print-format.landscape {
        max-width: 26.9cm;
        width: 26.9cm;
    }
    .print-format.portrait {
        max-width: 21.1cm;
        width: 21.1cm;
    }
}
@page {
    size: 21.1cm 26.9cm portrait;
     margin: 0;
}
/* US Letter PORTRAIT page size ENDS */

html:
{% set adv = -1 %}

{% set ns = namespace(party="", party_type="") %}

{% for acc in doc.get("accounts") %}
    {% if acc.party and not ns.party %}
        {% set ns.party = acc.party %}
        {% set ns.party_type = acc.party_type %}
    {% endif %}
{% endfor %}

{% set tin = "" %}
{% if ns.party and ns.party_type == "Customer" %}
    {% set tin = frappe.db.get_value("Customer", ns.party, "tax_id") %}
{% elif ns.party and ns.party_type == "Supplier" %}
    {% set tin = frappe.db.get_value("Supplier", ns.party, "tax_id") %}
{% endif %}

<!-- PARTY NAME -->
<div role="presentation" dir="ltr"
  style="text-align: left; border:0px solid; position: absolute; left: 2.6cm; width:9.5cm; top: {{ 4.7 + adv }}cm; font-size: 13px; font-family: arial; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">
  
  {{ ns.party.upper() if ns.party else "&nbsp;" }}
</div>

<!-- POSTING DATE -->
<div role="presentation" dir="ltr"
  style="text-align: center; border:0px solid; position: absolute; right:1.5cm; width:4cm; top: {{ 4.7 + adv }}cm; font-size: 13px; font-family: calibri; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">
  
  {{ frappe.utils.formatdate(doc.posting_date, "MMMM dd, yyyy") or "&nbsp;" }}
</div>

<!-- TIN -->
<div role="presentation" dir="ltr"
  style="text-align: left; border:0px solid; position: absolute; right: 1cm; width:4cm; top: {{ 6.6 + adv }}cm; font-size: 13px; font-family: calibri; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">
  
  {{ tin or "&nbsp;" }}
</div>

<!-- ADDRESS -->
<div role="presentation" dir="ltr"
  style="border:0px solid; position: absolute; left: 2.6cm; width:10.5cm; top: {{ 5.4 + adv }}cm; font-size: 1.5vw; max-width: 11cm; height: 1cm; font-family: Arial; box-sizing: border-box; display: flex; align-items: flex-end; justify-content: flex-start; white-space: normal; overflow-wrap: break-word; word-wrap: break-word;">

  {% set address_name = frappe.db.get_value("Dynamic Link", {
    "link_doctype": ns.party_type,
    "link_name": ns.party,
    "parenttype": "Address"
  }, "parent") %}

  {% set addr1 = frappe.db.get_value("Address", address_name, "address_line1") %}
  {% set addr2 = frappe.db.get_value("Address", address_name, "address_line2") %}
  {% set addr3 = frappe.db.get_value("Address", address_name, "city") %}
  {% set addr4 = frappe.db.get_value("Address", address_name, "state") %}

  {{ ([addr1, addr2, addr3, addr4] | select | map('trim') | join(', ')).upper() or "&nbsp;" }}
</div>

<!-- ACCOUNT ENTRIES -->
<div role="presentation" dir="ltr"
  style="text-align: center; border:0px solid; position: absolute; left:1cm; right: 1.5cm; top: {{ 9.5 + adv }}cm; font-size: 13px; font-family: calibri; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">

 
  
 {% set total_credit = namespace(val=0) %}

{% for acc in doc.accounts %}

    {% if acc.credit and acc.credit > 0 %}

        {% set total_credit.val = total_credit.val + acc.credit %}

        <div style="display: flex; height: 26.5px; border:0px solid">

            <!-- ACCOUNT / ADVANCE BILLING -->
            <div style="width: 80%; padding: 8px; border:0px solid; text-align:left; margin-left: 185px;">
                <span style="color:black !important">

                    {% if "Advance Billing" in acc.account %}
                        Advance Billing
                    {% else %}
                        {{ acc.account }}
                    {% endif %}

                </span>
            </div>

            <!-- CREDIT -->
            <div style="width: 20%; padding: 8px; border:0px solid; text-align:right">
                <span style="color:black !important">
                    {{ "{:,.2f}".format(acc.credit) }}
                </span>
            </div>

        </div>

    {% endif %}

{% endfor %}

  <!-- REMARKS -->
  <div style="display: flex; height: 26.5px;">
    <div style="width: 100%; padding: 8px; text-align:left;">
      {{ doc.user_remark or "" }}
    </div>
  </div>

</div>

<!-- GRAND TOTAL -->
<div role="presentation" dir="ltr"
  style="text-align: right; border:0px solid; position: absolute; right: 1.5cm; width:3cm; top: {{ 20.5 + adv }}cm; font-size: 13px; font-family: calibri; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">

  {{ "{:,.2f}".format(total_credit.val) if total_credit.val else "" }}
</div>

<!-- PREPARED BY -->
<div role="presentation" dir="ltr"
  style="text-align: center; border:0px solid; position: absolute; left: 1.2cm; top: {{ 21.5 + adv }}cm; font-size: 13px; font-family: calibri; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">

  <div style="width: 3.5cm; height: 1.4cm; font-size: 13px; font-family: calibri;
      background: transparent url('{{ frappe.db.get_value("User", doc.owner, "signature") or "" }}')
      no-repeat center;
      background-size: contain;
      text-align: center;
      border: none;">

    <br><br>

    {{ frappe.db.get_value("User", doc.owner, "full_name") or "" }}
  </div>
</div>

<!-- APPROVED BY -->
<div role="presentation" dir="ltr"
  style="text-align: center; border:0px solid; position: absolute; left: 5cm; top: {{ 21.5 + adv }}cm; font-size: 13px; font-family: calibri; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">

  <div style="width: 3.5cm; height: 1.4cm; font-size: 13px; font-family: calibri;
      background: transparent url('{{ frappe.db.get_value("User", doc.approver, "signature") or "" }}')
      no-repeat center;
      background-size: contain;
      text-align: center;
      border: none;">

    <br><br>

    {{ frappe.db.get_value("User", doc.approver, "full_name") or "" }}
  </div>
</div>
